	tokens := Tokenize(KindXML, `<!-- c --><root a="1">text</root>`)

	classes := map[TokenClass]bool{}
	for _, token := range tokens {
		classes[token.Class] = true
	}
	for _, want := range []TokenClass{ClassComment, ClassTag, ClassAttr, ClassString} {
