func TestTOMLKeysAreClassifiedAsKeys(t *testing.T) {
	tokens := Tokenize(KindTOML, "# note\ntitle = \"devdesk\"\n\n[app]\nport = 8080\ndebug = true\n")

	assertFirstPerClass(t, tokens, map[TokenClass]string{
		ClassComment: "# note",
		ClassKey:     "title",
		ClassPunct:   "=",
		ClassString:  `"devdesk"`,
